struct JobConstructionProducer{source:OriginalCallerSourceLoan,submitted:RetainedCloneProgress}
/// 🧵️ Borrows the actual Job turn and its originally selected physical budget.
pub(super) struct JobConstructionTurn<'view,'turn,'source>{pub(super) context:&'view std::sync::Mutex<&'turn mut StepContext<'source>>,pub(super) grant:RetainedCloneGrant,pub(super) start:RetainedCloneProgress}
